<?php
declare(strict_types=1);require_once __DIR__.'/../includes/db.php';$pdo=getDB();$file=__DIR__.'/rockharz_articles_data.json';if(!is_file($file)){fwrite(STDERR,"Datendatei fehlt.\n");exit(1);}$rows=json_decode((string)file_get_contents($file),true,512,JSON_THROW_ON_ERROR);$pdo->beginTransaction();
try{$cat=(int)$pdo->query("SELECT id FROM categories WHERE slug='rockharz-open-air' LIMIT 1")->fetchColumn();if(!$cat)throw new RuntimeException('Kategorie rockharz-open-air fehlt');$sql="INSERT INTO articles (title,slug,content,excerpt,category_id,author,featured_image,status,created_at,updated_at) VALUES (:title,:slug,:content,:excerpt,:cat,'Redaktion',:image,'published',:created,NOW()) ON DUPLICATE KEY UPDATE title=VALUES(title),content=VALUES(content),excerpt=VALUES(excerpt),category_id=VALUES(category_id),featured_image=VALUES(featured_image),status='published',created_at=VALUES(created_at),updated_at=NOW()";$st=$pdo->prepare($sql);foreach($rows as $x)$st->execute([':title'=>$x['title'],':slug'=>$x['slug'],':content'=>$x['content'],':excerpt'=>$x['excerpt'],':cat'=>$cat,':image'=>$x['image'],':created'=>$x['date'].' 12:00:00']);$pdo->commit();echo "Kategorie {$cat}; ".count($rows)." offizielle ROCKHARZ-Meldungen veröffentlicht.\n";}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();fwrite(STDERR,$e->getMessage()."\n");exit(1);}
